INSERT INTO `space_versions` (`version`, `title`, `summary`, `created_at`) VALUES
('v78', '豆包切换模型不再另开官网对话', '起因：豆包切换模型已经生效，但切换后同一个房间在官网变成了新开的对话。此前空间在保存新选型时（设置面板保存与聊天框工具栏切换两条路径都会）把该智能体名下所有房间的官网对话续接记录一并清掉，下一条回复只能按新选型从零新建官网对话——这是当年为了让切换「看起来生效」留下的做法。现在模型选择包本来就随每一次发送的第一条请求发出，续发时同样带着，所以切换选型不再清续接记录：下一条回复在房间原来的官网对话里续发、带着新选型，同一个房间在官网始终是同一个对话。设置里三处说明文案同步改为这一口径。仍然会清续接记录的只剩账号身份变更（换了另一个账号的凭证）——那时旧对话属于旧账号，必须按新账号重新开始，与切换模型无关。诚实边界不变：空间只能证明新选型确实随续发请求发了出去，最终由哪个模型回答由豆包按账号决定、回复里没有可验证标记，需在生产用真实账号切换一次后到官网同一对话里确认。', 1795189500000);
